// Shared debounce helper, dark-mode bootstrap and the Arabic/English translation layer (T, LOC, static page text).

window.debounce = function(fn, wait) {
  let t;
  return function(...args) {
    clearTimeout(t);
    t = setTimeout(() => fn.apply(this, args), wait || 250);
  };
};

// Runs immediately so a saved dark theme is applied before the first paint.
(function initDarkMode() {
  try {
    const saved = localStorage.getItem('ep_theme');
    const prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    applyTheme(saved || (prefersDark ? 'dark' : 'light'));
  } catch (e) { }
})();
function applyTheme(theme) {
  document.body.setAttribute('data-theme', theme);
  ['themeToggleIcon', 'themeToggleIconPre', 'themeToggleIconGate'].forEach(id => {
    const icon = document.getElementById(id);
    if (icon) icon.textContent = theme === 'dark' ? '☀️' : '🌙';
  });
  document.dispatchEvent(new CustomEvent('themechange', { detail: { theme } }));
}

// Canvas drawings (charts) cannot use CSS variables, so design tokens are resolved here.
function cssToken(name) {
  try { return getComputedStyle(document.body).getPropertyValue(name).trim(); } catch (e) { return ''; }
}
function cssTokenAlpha(name, alpha) {
  const value = cssToken(name);
  const hex = value.replace('#', '');
  if (!/^[0-9a-f]{6}$/i.test(hex)) return value;
  const n = parseInt(hex, 16);
  return `rgba(${n >> 16}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`;
}
function toggleDarkMode() {
  const current = document.body.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
  const next = current === 'dark' ? 'light' : 'dark';
  applyTheme(next);
  try { localStorage.setItem('ep_theme', next); } catch (e) { }
}

